import { useRouter } from 'vue-router'
import { refreshCsrfToken } from '../data/session'
import { notifyError, notifySuccess } from '../composables/toast'
import StockOutUnitCards from '../components/StockOutUnitCards.vue'

const router = useRouter()
const DOCTYPE = 'Stock Out Motor'
const TIPE_LIST = ['Lelang', 'BBG', 'Pinjam', 'Titipan', 'Tebus']

function today() {
	const d = new Date()
	return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(
		d.getDate()
	).padStart(2, '0')}`
}

const form = reactive({
	tipe: '',
	tanggal_keluar: today(),
	tebus_motor_nasabah: '',
	id_dealer: '',
	nama_pembeli: '',
	nama_pic: '',
	alasan_pinjam: '',
	tanggal_kembali_rencana: '',
	catatan: '',
	items: [],
})
const saving = ref(false)
const saveError = ref('')

const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

// Petunjuk unit yang boleh dipilih per tipe (cerminan aturan validate server).
const UNIT_HINT = {
	Lelang: 'Unit: Tarikan · Tipe Unit Lelang · Stok AYDA.',
	BBG: 'Unit: Tarikan · Tipe Unit BBG · Stok AYDA · dealer cocok. Harga terisi dari Nominal BBG.',
	Pinjam: 'Unit: status Stok AYDA atau Stok Titipan.',
	Titipan: 'Unit: Titipan · Stok Titipan.',
	Tebus: 'Unit: Tarikan · Stok Tebus.',
}
const unitHint = computed(() => UNIT_HINT[form.tipe] || '')

// ---- Ganti tipe → kosongkan items (mirror desk: konfirmasi dulu) -----------
const confirmTipe = reactive({ open: false, next: '' })
function onPickTipe(t) {
	if (t === form.tipe) return
	if (form.items.length) {
		confirmTipe.next = t
		confirmTipe.open = true
		return
	}
	setTipe(t)
}
function applyTipeChange() {
	setTipe(confirmTipe.next)
	form.items = []
	confirmTipe.open = false
}
function setTipe(t) {
	form.tipe = t
	saveError.value = ''
	// Kosongkan field yang tak relevan agar tidak terkirim silang.
	if (t !== 'Tebus') form.tebus_motor_nasabah = ''
	if (t !== 'Lelang' && t !== 'BBG') {
		form.id_dealer = ''
		form.nama_pembeli = ''
	}
	if (!['Pinjam', 'Titipan', 'Tebus'].includes(t)) form.nama_pic = ''
	if (t !== 'Pinjam') {
		form.alasan_pinjam = ''
		form.tanggal_kembali_rencana = ''
	}
}

// ---- Link picker (tebus_motor_nasabah / id_dealer) -------------------------
const openLink = ref('')
const linkSearch = ref('')
const linkResults = ref([])
const linkLoading = ref(false)
let linkTimer = null

// Konfigurasi per Link. `titleField` dipakai bila `name` bukan teks yang bisa
// dibaca: Data Mokas ber-autoname hash (mis. "t76l6sj1qe") dengan title_field
// `nama_mokas` → yang ditampilkan harus NAMA DEALER, bukan kodenya.
// tebus_motor_nasabah namanya sudah readable & difilter Approved + submitted
// (persis set_query desk).
function linkConfig(fieldname) {
	if (fieldname === 'tebus_motor_nasabah') {
		return {
			doctype: 'Tebus Motor Nasabah',
			titleField: null,
			filters: [
				['docstatus', '=', 1],
				['workflow_state', '=', 'Approved'],
			],
		}
	}
	return { doctype: 'Data Mokas', titleField: 'nama_mokas', filters: [] }
}

// Label tampilan per Link terpilih (value = name/kode, label = nama yang dibaca).
const linkLabels = reactive({})
function linkDisplay(fieldname) {
	const v = form[fieldname]
	if (!v) return ''
	return linkLabels[fieldname] || v
}

function toggleLink(fieldname) {
	if (openLink.value === fieldname) {
		openLink.value = ''
		return
	}
	openLink.value = fieldname
	linkSearch.value = ''
	fetchLink(fieldname, '')
}
async function fetchLink(fieldname, query) {
	linkLoading.value = true
	linkResults.value = []
	try {
		const cfg = linkConfig(fieldname)
		const fields = cfg.titleField ? ['name', cfg.titleField] : ['name']
		const params = new URLSearchParams({
			doctype: cfg.doctype,
			fields: JSON.stringify(fields),
			limit_page_length: '20',
			order_by: cfg.titleField ? `${cfg.titleField} asc` : 'modified desc',
		})
		if (cfg.filters.length) params.set('filters', JSON.stringify(cfg.filters))
		// Cari berdasarkan nama yang dibaca DAN kode.
		if (query) {
			const ors = [['name', 'like', `%${query}%`]]
			if (cfg.titleField) ors.push([cfg.titleField, 'like', `%${query}%`])
			params.set('or_filters', JSON.stringify(ors))
		}
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		if (!res.ok) throw new Error((json && json.exception) || `HTTP ${res.status}`)
		linkResults.value = (json.message || []).map((r) => ({
			value: String(r.name),
			label: (cfg.titleField && r[cfg.titleField]) || String(r.name),
		}))
	} catch (e) {
		linkResults.value = []
		notifyError(e, 'Gagal memuat pilihan')
	} finally {
		linkLoading.value = false
	}
}
function onLinkSearch() {
	clearTimeout(linkTimer)
	linkTimer = setTimeout(() => fetchLink(openLink.value, linkSearch.value.trim()), 300)
}
function pickLink(fieldname, opt) {
	const prev = form[fieldname]
	form[fieldname] = opt.value
	linkLabels[fieldname] = opt.label
	openLink.value = ''
	// Ganti dealer → kosongkan unit (unit BBG terfilter per dealer).
	if (fieldname === 'id_dealer' && prev && prev !== opt.value) form.items = []
}

// ---- Date picker in-app ---------------------------------------------------
const DP_WEEKDAYS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const DP_MONTHS = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]
const datePicker = reactive({ open: false, fieldname: '', label: '', cursor: new Date() })
function dpYmd(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const day = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}
function dpParse(s) {
	const [y, m, d] = String(s).split('-').map(Number)
	return new Date(y, (m || 1) - 1, d || 1)
}
function openDatePicker(fieldname, label) {
	datePicker.fieldname = fieldname
	datePicker.label = label
	const base = form[fieldname] || dpYmd(new Date())
	const d = dpParse(base)
	datePicker.cursor = new Date(d.getFullYear(), d.getMonth(), 1)
	datePicker.open = true
}
const dpLabel = computed(
	() => `${DP_MONTHS[datePicker.cursor.getMonth()]} ${datePicker.cursor.getFullYear()}`
)
const dpDays = computed(() => {
	const year = datePicker.cursor.getFullYear()
	const month = datePicker.cursor.getMonth()
	const first = new Date(year, month, 1)
	const startOffset = (first.getDay() + 6) % 7
	const daysInMonth = new Date(year, month + 1, 0).getDate()
	const cells = []
	for (let i = 0; i < startOffset; i++) cells.push(null)
	for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d))
	return cells
})
function dpPrevMonth() {
	datePicker.cursor = new Date(
		datePicker.cursor.getFullYear(),
		datePicker.cursor.getMonth() - 1,
		1
	)
}
function dpNextMonth() {
	datePicker.cursor = new Date(
		datePicker.cursor.getFullYear(),
		datePicker.cursor.getMonth() + 1,
		1
	)
}
function dpDayClass(date) {
	const s = dpYmd(date)
	if (s === form[datePicker.fieldname]) return 'rounded-full bg-primary font-semibold text-ui-onPrimary'
	if (s === dpYmd(new Date())) return 'rounded-full font-semibold text-primary'
	return 'rounded-full text-ui-ink-gray-700 hover:bg-ui-surface-gray-100'
}
function pickDate(date) {
	form[datePicker.fieldname] = dpYmd(date)
	datePicker.open = false
}
function clearDate() {
	if (datePicker.fieldname) form[datePicker.fieldname] = ''
	datePicker.open = false
}
function formatDateDisplay(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}

// ---- Simpan ----------------------------------------------------------------
function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}

// Validasi client — cerminan aturan validate server (_assert_tipe_required_fields).
function validate() {
	const missing = []
	if (!form.tipe) missing.push('Tipe')
	if (!form.tanggal_keluar) missing.push('Tanggal Keluar')
	if (form.tipe === 'Tebus' && !form.tebus_motor_nasabah) missing.push('Tebus Motor Nasabah')
	if (form.tipe === 'Lelang' || form.tipe === 'BBG') {
		if (!form.id_dealer) missing.push('Nama Dealer')
		if (!String(form.nama_pembeli || '').trim()) missing.push('Nama Pembeli')
	}
	if (['Pinjam', 'Titipan'].includes(form.tipe) && !String(form.nama_pic || '').trim())
		missing.push('Nama PIC')
	if (form.tipe === 'Pinjam' && !form.tanggal_kembali_rencana)
		missing.push('Tanggal Kembali (Rencana)')
	const valid = (form.items || []).filter((u) => u.motor_tarikan)
	if (!valid.length) missing.push('minimal 1 unit (List Unit)')
	return missing
}

async function submit() {
	saveError.value = ''
	const missing = validate()
	if (missing.length) {
		saveError.value = `Lengkapi: ${missing.join(', ')}`
		notifyError(saveError.value, 'Data belum lengkap')
		window.scrollTo({ top: 0, behavior: 'smooth' })
		return
	}
	saving.value = true
	try {
		await refreshCsrfToken()
		const items = (form.items || [])
			.filter((u) => u.motor_tarikan)
			.map((u) => ({ doctype: 'Stock Out Motor Item', ...u }))
		// total_unit & total_tagihan dihitung server (validate hook).
		const doc = {
			doctype: DOCTYPE,
			tipe: form.tipe,
			tanggal_keluar: form.tanggal_keluar,
			catatan: form.catatan,
			items,
		}
		if (form.tipe === 'Tebus') doc.tebus_motor_nasabah = form.tebus_motor_nasabah
		if (form.tipe === 'Lelang' || form.tipe === 'BBG') {
			doc.id_dealer = form.id_dealer
			doc.nama_pembeli = form.nama_pembeli
		}
		if (['Pinjam', 'Titipan', 'Tebus'].includes(form.tipe)) doc.nama_pic = form.nama_pic
		if (form.tipe === 'Pinjam') {
			doc.alasan_pinjam = form.alasan_pinjam
			doc.tanggal_kembali_rencana = form.tanggal_kembali_rencana
		}
		const res = await fetch('/api/method/frappe.client.insert', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		notifySuccess('Stock Out Motor berhasil dibuat.')
		const name = json.message?.name
		if (name) router.push({ name: 'StockOutMotorDetail', params: { name } })
		else router.push({ name: 'StockOutMotor' })
	} catch (e) {
		saveError.value = e.message || String(e)
		notifyError(e, 'Gagal menyimpan')
		window.scrollTo({ top: 0, behavior: 'smooth' })
	} finally {
		saving.value = false
	}
}
</script>
